#!/usr/bin/env bash
# Writes AmberXCore-sources.cmake from the compile gate's own PASS lines, so
# the CMake target compiles exactly the set the gate measured — no more, no
# less. Kept as its own script because the pipeline is all backslashes and
# CMake variable syntax, which is nobody's idea of a safe one-liner.
set -euo pipefail
cd "$(dirname "$0")"
[ -f probe-out/results.txt ] || { echo "no probe-out/results.txt — run run-probe.sh first" >&2; exit 1; }
{
  echo '# AmberXCore-sources.cmake — GENERATED by gen-sources.sh from the compile gate.'
  echo '# Exactly the files that passed. Change the allowlist (LICENSE-MATRIX.md) and'
  echo '# re-run run-probe.sh; do not edit this file.'
  echo 'set(AMBERX_CORE_SOURCES'
  grep '^PASS ' probe-out/results.txt | awk '{ print $2 }' | tr '\\' '/' | sort \
    | sed 's/^/    ${AMBERX_UPSTREAM}\/xserver\//'
  echo ')'
} > AmberXCore-sources.cmake
echo "AmberXCore-sources.cmake: $(grep -c 'xserver/' AmberXCore-sources.cmake) sources"
